local ReplicatedStorage = game:GetService("ReplicatedStorage")
local t = {
	Name = "Vintage Rudie",
	Mastery = true,
	OverwriteAnimations = {},
	FaceTextures = {
		Normal = "rbxassetid://92994092090592",
		Hurt = "rbxassetid://113785447525723",
		Blink = "rbxassetid://139975153263997"
	},
	USE_SKIN_MODEL = false
}

function t.ApplySkin(p1) --[[ ApplySkin | Line: 18 | Upvalues: t (copy), ReplicatedStorage (copy) ]]
	for k, v in pairs(p1:GetDescendants()) do
		if v:IsA("MeshPart") and v.Name ~= "Nose" then
			v.TextureID = t.FaceTextures.Normal
		end
	end

	if not require(ReplicatedStorage.SharedUtils.Universe):IsGame() then
		return
	end

	local Nose = p1:WaitForChild("Nose", 5)

	if Nose then
		Nose.Color = Color3.new(255/255, 255/255, 255/255)
		Nose:SetAttribute("BlackoutColor", Color3.new(255/255, 255/255, 255/255))

		for k, v in pairs(Nose:GetDescendants()) do
			if v:IsA("PointLight") or v:IsA("SpotLight") then
				v.Color = Color3.new(255/255, 255/255, 255/255)
			end
		end
	else
		warn("[VintageRudie] Nose part not found - skipping nose customization")
	end

	local HumanoidRootPart = p1:WaitForChild("HumanoidRootPart")

	for k, v in pairs(HumanoidRootPart:GetDescendants()) do
		if v:IsA("PointLight") or v:IsA("SpotLight") then
			v.Color = Color3.new(255/255, 255/255, 255/255)
		end
	end
end

return t